# We'll use Python with backtracking or use pysat
# Let's think about encoding this as SAT

# Variables:
# x[i] = value at position i (0..13)
# d[i] = |x[i+1] - x[i]| for i=0..12

# We have fixed: x[6]=3, x[12]=6, d[3]=10, d[11]=2

# Let's try a simple backtracking approach first with constraint propagation

def solve_all_interval(n, fixed_x, fixed_d):
    # fixed_x: dict pos->value
    # fixed_d: dict pos->diff (for diff between pos and pos+1)

    # x values: 0..n-1
    # d values: 1..n-1

    all_vals = set(range(n))
    all_diffs = set(range(1, n))

    # We'll use backtracking with pruning

    x = [None] * n
    d = [None] * (n-1)

    # Apply fixed values
    for pos, val in fixed_x.items():
        x[pos] = val
    for pos, val in fixed_d.items():
        d[pos] = val

    used_vals = set(v for v in x if v is not None)
    used_diffs = set(v for v in d if v is not None)

    # Check consistency
    if len(used_vals) != sum(1 for v in x if v is not None):
        return None
    if len(used_diffs) != sum(1 for v in d if v is not None):
        return None

    # Check that fixed diffs are consistent with fixed x values
    for i in range(n-1):
        if x[i] is not None and x[i+1] is not None and d[i] is not None:
            if abs(x[i] - x[i+1]) != d[i]:
                return None

    # Order of filling: let's try positions that are most constrained

    def backtrack():
        nonlocal x, d

        # Check if complete
        if all(v is not None for v in x) and all(v is not None for v in d):
            # Verify all constraints
            for i in range(n-1):
                if abs(x[i] - x[i+1]) != d[i]:
                    return None
            if set(x) != set(range(n)):
                return None
            if set(d) != set(range(1, n)):
                return None
            return x[:]

        # Find most constrained variable
        # For x positions
        best_var = None
        best_domain_size = float('inf')

        for i in range(n):
            if x[i] is None:
                # Compute possible values
                possible = set(range(n)) - used_vals
                # Also check consistency with adjacent diffs
                for val in list(possible):
                    ok = True
                    if i > 0 and d[i-1] is not None:
                        if abs(x[i-1] - val) != d[i-1]:
                            ok = False
                    if i < n-1 and d[i] is not None:
                        if abs(val - x[i+1]) != d[i]:
                            ok = False
                    if not ok:
                        possible.remove(val)
                if len(possible) < best_domain_size:
                    best_domain_size = len(possible)
                    best_var = ('x', i, possible)

        for i in range(n-1):
            if d[i] is None:
                possible = set(range(1, n)) - used_diffs
                for val in list(possible):
                    ok = True
                    if x[i] is not None and x[i+1] is not None:
                        if abs(x[i] - x[i+1]) != val:
                            ok = False
                    if not ok:
                        possible.remove(val)
                if len(possible) < best_domain_size:
                    best_domain_size = len(possible)
                    best_var = ('d', i, possible)

        if best_var is None or best_domain_size == 0:
            return None

        typ, idx, domain = best_var

        for val in sorted(domain):
            old_x = x[:]
            old_d = d[:]
            old_used_vals = used_vals.copy()
            old_used_diffs = used_diffs.copy()

            if typ == 'x':
                x[idx] = val
                used_vals.add(val)
                # Propagate: if adjacent x's are known, set d
                if idx > 0 and x[idx-1] is not None and d[idx-1] is None:
                    diff = abs(x[idx-1] - val)
                    if diff in used_diffs:
                        x[idx] = None
                        used_vals.remove(val)
                        continue
                    d[idx-1] = diff
                    used_diffs.add(diff)
                if idx < n-1 and x[idx+1] is not None and d[idx] is None:
                    diff = abs(val - x[idx+1])
                    if diff in used_diffs:
                        x[idx] = None
                        used_vals.remove(val)
                        continue
                    d[idx] = diff
                    used_diffs.add(diff)
            else:  # d
                d[idx] = val
                used_diffs.add(val)
                # Propagate: if both x's are known, check consistency
                if x[idx] is not None and x[idx+1] is not None:
                    if abs(x[idx] - x[idx+1]) != val:
                        d[idx] = None
                        used_diffs.remove(val)
                        continue

            result = backtrack()
            if result is not None:
                return result

            # Restore
            x = old_x
            d = old_d
            used_vals = old_used_vals
            used_diffs = old_used_diffs

        return None

    return backtrack()

