def solve_n_queens(n):
    # Simple backtracking solver
    def is_safe(board, row, col):
        # Check column
        for i in range(row):
            if board[i] == col:
                return False
            # Check diagonals
            if abs(board[i] - col) == abs(i - row):
                return False
        return True

    def backtrack(board, row):
        if row == n:
            return board[:]
        for col in range(n):
            if is_safe(board, row, col):
                board.append(col)
                result = backtrack(board, row + 1)
                if result:
                    return result
                board.pop()
        return None

    return backtrack([], 0)

